# src/workpeg/runtime.py

import hmac
import importlib
import json
import os
import sys
import traceback
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from typing import Any, Callable, Dict, Tuple


DEFAULT_ENTRYPOINT = "app.main:main"
DEFAULT_HOST = "0.0.0.0"
DEFAULT_PORT = 8000


#: Set by a dev function's runner on the container it starts (``workpeg
#: project serve --fake-cloud``, Docker mode). When set, ``POST /invoke``
#: answers only a request carrying it in :data:`INVOKE_KEY_HEADER`, with a
#: JSON Content-Type: a page open in the developer's browser can POST to
#: loopback, but cannot know the key, and a ``text/plain`` form post, which
#: a browser sends with no preflight, is refused whatever it carries. Unset,
#: as on every deployed container, the runtime answers as it always has.
INVOKE_KEY_ENV = "WORKPEG_INVOKE_KEY"
INVOKE_KEY_HEADER = "X-Workpeg-Invoke-Key"

#: The one body of every refusal for a missing or wrong key or a body that
#: is not declared as JSON. It says nothing about which.
INVOKE_REFUSED = {
    "status": "error",
    "error_type": "unauthorized",
    "error": "This runtime answers only its own runner.",
}


class FunctionRuntimeError(Exception):
    pass


def _json_dump(obj: Any) -> str:
    try:
        return json.dumps(obj)
    except TypeError as exc:
        raise FunctionRuntimeError(
            f"Function returned a non-JSON-serializable value: {exc}"
        ) from exc


def parse_entrypoint(entry: str) -> Tuple[str, str]:
    try:
        module_name, func_name = entry.split(":", 1)
        module_name = module_name.strip()
        func_name = func_name.strip()
        if not module_name or not func_name:
            raise ValueError
        return module_name, func_name
    except ValueError:
        raise FunctionRuntimeError(
            f"Invalid FUNCTION_ENTRYPOINT format: '{entry}'. "
            "Expected 'module.path:func_name'."
        )


def _ensure_cwd_on_syspath() -> None:
    cwd = os.getcwd()
    if cwd not in sys.path:
        sys.path.insert(0, cwd)


def load_function(entry: str | None = None):
    _ensure_cwd_on_syspath()

    entry = entry or os.getenv("FUNCTION_ENTRYPOINT", DEFAULT_ENTRYPOINT)
    module_name, func_name = parse_entrypoint(entry)

    importlib.invalidate_caches()

    # Clear module + parent packages from cache
    parts = module_name.split(".")
    for i in range(len(parts), 0, -1):
        candidate = ".".join(parts[:i])
        sys.modules.pop(candidate, None)

    try:
        module = importlib.import_module(module_name)
    except Exception as exc:
        raise FunctionRuntimeError(
            f"Failed to import module '{module_name}' from '{entry}': {exc}"
        ) from exc

    try:
        fn = getattr(module, func_name)
    except AttributeError as exc:
        raise FunctionRuntimeError(
            f"Module '{module_name}' does not define '{func_name}' from '{entry}'."
        ) from exc

    if not callable(fn):
        raise FunctionRuntimeError(
            f"'{entry}' is not callable. Expected a function."
        )

    return fn


def read_request(request_file: "str | None" = None) -> Dict[str, Any]:
    """The envelope, from stdin, or from *request_file* when one is given so
    that stdin can stay the terminal (``breakpoint()`` in a function run by
    ``--debug``)."""
    try:
        if request_file is not None:
            with open(request_file, encoding="utf-8") as handle:
                raw = handle.read()
        else:
            raw = sys.stdin.read()
        if not raw.strip():
            raise FunctionRuntimeError("No input received on stdin.")
        data = json.loads(raw)
        if not isinstance(data, dict):
            raise FunctionRuntimeError("Input JSON must be a JSON object.")
        return data
    except json.JSONDecodeError as exc:
        raise FunctionRuntimeError(f"Invalid JSON input: {exc}") from exc


def invoke_function(
    fn: Callable[[Dict[str, Any], Dict[str, Any]], Any],
    request: Dict[str, Any],
) -> Tuple[Dict[str, Any], int]:
    try:
        context = request.get("context", {})
        payload = request.get("payload", {})

        if not isinstance(context, dict):
            raise FunctionRuntimeError("Field 'context' must be a JSON object.")
        if not isinstance(payload, dict):
            raise FunctionRuntimeError("Field 'payload' must be a JSON object.")

        result = fn(context, payload)
        return {"status": "success", "result": result}, 0

    except FunctionRuntimeError as e:
        return {
            "status": "error",
            "error_type": "runtime_error",
            "error": str(e),
        }, 1

    except Exception as e:
        trace = traceback.format_exc()
        return {
            "status": "error",
            "error_type": "user_error",
            "error": str(e),
            "trace": trace,
        }, 1


def run_once(entrypoint: str | None = None,
             request_file: "str | None" = None,
             answer_file: "str | None" = None) -> int:
    """Run one call. The answer is printed on stdout as one JSON line, or
    written to *answer_file* when one is given, so that stdout can stay the
    terminal for a debugger (``--debug``)."""
    def answer(obj: Dict[str, Any]) -> None:
        if answer_file is None:
            print(_json_dump(obj), flush=True)
            return
        with open(answer_file, "w", encoding="utf-8") as handle:
            handle.write(_json_dump(obj))

    try:
        fn = load_function(entrypoint)
        request = (read_request() if request_file is None
                   else read_request(request_file))

        response, exit_code = invoke_function(fn, request)

        answer(response)
        return exit_code

    except FunctionRuntimeError as e:
        err_output = {
            "status": "error",
            "error_type": "runtime_error",
            "error": str(e),
        }
        answer(err_output)
        print(f"[workpeg runtime] runtime_error: {e}", file=sys.stderr)
        return 1

    except Exception as e:
        trace = traceback.format_exc()
        err_output = {
            "status": "error",
            "error_type": "user_error",
            "error": str(e),
            "trace": trace,
        }
        answer(err_output)
        print(f"[workpeg runtime] user_error: {e}\n{trace}", file=sys.stderr)
        return 1


def _take_invoke_key() -> "bytes | None":
    """The invoke key, taken out of ``os.environ`` so that the function
    this runtime imports does not find it there."""
    value = os.environ.pop(INVOKE_KEY_ENV, None)
    return value.encode("utf-8") if value else None


def _is_json(content_type: "str | None") -> bool:
    media = (content_type or "").split(";", 1)[0].strip().lower()
    return media == "application/json"


def make_server(host: str = DEFAULT_HOST,
                port: int = DEFAULT_PORT,
                entrypoint: str | None = None) -> ThreadingHTTPServer:
    """The runtime's HTTP server, bound and not yet serving."""
    invoke_key = _take_invoke_key()
    fn = load_function(entrypoint)

    class Handler(BaseHTTPRequestHandler):
        def _send_json(self, status_code: int, payload: Dict[str, Any]) -> None:
            body = _json_dump(payload).encode("utf-8")
            self.send_response(status_code)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def do_GET(self) -> None:
            if self.path == "/healthz":
                self._send_json(200, {"status": "ok"})
                return
            self._send_json(404, {"status": "error", "error": "Not found"})

        def do_POST(self) -> None:
            if self.path != "/invoke":
                self._send_json(404, {"status": "error", "error": "Not found"})
                return

            if invoke_key is not None:
                given = (self.headers.get(INVOKE_KEY_HEADER) or "").encode(
                    "utf-8", "replace")
                # Both checks always run, so the time taken says nothing
                # about which failed.
                key_ok = hmac.compare_digest(given, invoke_key)
                if not (key_ok and _is_json(self.headers.get("Content-Type"))):
                    self._send_json(401, INVOKE_REFUSED)
                    return

            try:
                content_length = int(self.headers.get("Content-Length", "0"))
                raw = self.rfile.read(content_length).decode("utf-8")
                request = json.loads(raw)

                if not isinstance(request, dict):
                    raise FunctionRuntimeError("Input JSON must be a JSON object.")

                response, exit_code = invoke_function(fn, request)
                self._send_json(200 if exit_code == 0 else 400, response)

            except json.JSONDecodeError as exc:
                self._send_json(
                    400,
                    {
                        "status": "error",
                        "error_type": "runtime_error",
                        "error": f"Invalid JSON input: {exc}",
                    },
                )
            except Exception as exc:
                self._send_json(
                    500,
                    {
                        "status": "error",
                        "error_type": "runtime_error",
                        "error": str(exc),
                        "trace": traceback.format_exc(),
                    },
                )

        def log_message(self, fmt: str, *args: Any) -> None:
            print(f"[workpeg runtime] {fmt % args}", file=sys.stderr)

    return ThreadingHTTPServer((host, port), Handler)


def serve(host: str = DEFAULT_HOST,
          port: int = DEFAULT_PORT,
          entrypoint: str | None = None) -> None:
    server = make_server(host, port, entrypoint)
    print(f"[workpeg runtime] listening on http://{host}:{port}", file=sys.stderr)
    server.serve_forever()


def main(argv=None) -> None:
    argv = list(argv or [])
    if "--server" in argv:
        serve()
        return

    files = {}
    for flag in ("--request-file", "--answer-file"):
        if flag in argv:
            at = argv.index(flag)
            if at + 1 >= len(argv):
                print(f"[workpeg runtime] {flag} needs a path",
                      file=sys.stderr)
                sys.exit(2)
            files[flag[2:].replace("-", "_")] = argv[at + 1]
    sys.exit(run_once(**files) if files else run_once())


if __name__ == "__main__":
    # ``python -m workpeg.runtime``: how a dev function's runner and
    # ``workpeg function test`` start one call in a child process.
    main(sys.argv[1:])
